import{_ as o,o as n,c as i,a2 as a}from"./chunks/framework.BfI5QxtK.js";const h=JSON.parse('{"title":"Config API","description":"","frontmatter":{},"headers":[],"relativePath":"config.md","filePath":"config.md"}'),t={name:"config.md"};function s(r,e,c,l,d,g){return n(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="config-api" tabindex="-1">Config API <a class="header-anchor" href="#config-api" aria-label="Permalink to &quot;Config API&quot;">​</a></h1><p>This section documents the Lua API exposed by Gnoblin. Each reference page is named for its public <code>gnoblin.*</code> function. Configuration settings and their defaults are documented under <a href="/gnoblin/config/configure"><code>gnoblin.configure</code></a>.</p><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h2><ul><li><a href="/gnoblin/config/configure"><code>gnoblin.configure</code></a> — set compositor, shell, input and window-management options.</li><li><a href="/gnoblin/config/window_rule"><code>gnoblin.window_rule</code></a> — add a window or layer-surface rule.</li><li><a href="/gnoblin/config/permission_rule"><code>gnoblin.permission_rule</code></a> — add a portal permission rule.</li><li><a href="/gnoblin/config/shortcut"><code>gnoblin.shortcut</code></a> — add or update a named keyboard shortcut.</li><li><a href="/gnoblin/config/autostart"><code>gnoblin.autostart</code></a> — add or update a command run at login.</li><li><a href="/gnoblin/config/remove_shortcut"><code>gnoblin.remove_shortcut</code></a> — remove a named shortcut.</li><li><a href="/gnoblin/config/remove_autostart"><code>gnoblin.remove_autostart</code></a> — remove a named autostart entry.</li><li><a href="/gnoblin/config/load"><code>gnoblin.load</code></a> — load another Lua config file.</li><li><a href="/gnoblin/config/snapshot"><code>gnoblin.snapshot</code></a> — inspect a copy of the current config.</li><li><a href="/gnoblin/config/set"><code>gnoblin.set</code></a> — merge internal setting names into the config.</li><li><a href="/gnoblin/config/array"><code>gnoblin.array</code></a> — mark a Lua table as a list.</li></ul><p>The named views <code>gnoblin.configure.shortcuts</code> and <code>gnoblin.configure.autostart</code> read or update entries by name. See the <a href="/gnoblin/guides/shortcuts">shortcuts</a> and <a href="/gnoblin/guides/autostart">autostart</a> guides. <code>require</code> is Lua&#39;s global module loader, not a <code>gnoblin.*</code> function; see <a href="/gnoblin/config/load"><code>gnoblin.load</code></a> for its supported module behavior.</p><h2 id="first-config" tabindex="-1">First config <a class="header-anchor" href="#first-config" aria-label="Permalink to &quot;First config&quot;">​</a></h2><p>On first login, <code>gnoblin-session</code> copies the packaged reference config to <code>~/.config/gnoblin/init.lua</code> when no Lua or legacy config exists. It does not replace an existing config. Edit that file to configure Gnoblin.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gnoblinctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gnoblinctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span></span></code></pre></div><p>See <a href="/gnoblin/recipes">configuration recipes</a> for complete examples and the <a href="/gnoblin/guides/window_rules">guides</a> for task-based instructions.</p>`,9)])])}const u=o(t,[["render",s]]);export{h as __pageData,u as default};
